'use strict';const SistemaInfo={version:'1.0.0',parcial:1,materia:'Servicios Telematicos',anio:2026,semestre:'2026-02',getInfo(){return{version:this.version,parcial:this.parcial,materia:this.materia,timestamp:new Date().toISOString(),userAgent:navigator.userAgent}}};document.addEventListener('DOMContentLoaded',()=>console.log('Compresion HTTP activa',SistemaInfo.getInfo()));
